describe('Chart edge geometry', () => {
  it('renders with a single value, and with a marker at either end', () => {
    expect(render(<Chart chartType="line" values={[5]} width={200} height={100} dots />)).not.toBe('null');
    expect(render(
      <Chart chartType="line" values={[1, 2, 3]} width={200} height={100} marker={{ index: 0, label: 'first' }} />,
    )).toContain('first');
    expect(render(
      <Chart chartType="area" values={[1, 2, 3]} width={200} height={100} marker={{ index: 2, label: 'last' }} smooth />,
    )).toContain('last');
  });
  it('renders a bar chart with explicit colours, a gap and a radius', () => {
    expect(render(
      <Chart chartType="bar" values={[1, 2]} colors={['#f00', '#0f0']} gap={8} barRadius={4}
        trackColor="#eee" width={200} height={100} axisLabels={['a', 'b']} gridLines={2} />,
    )).not.toBe('null');
  });
  it('renders a donut with an inner radius and a start angle', () => {
    expect(render(
      <Chart chartType="donut" values={[1, 1, 1]} labels={['a', 'b', 'c']} innerRadius={0.6}
        startAngle={90} segmentGap={2} width={240} height={160} legend="bottom" />,
    )).not.toBe('null');
  });
});
